function CourtCard({ number, name, kind, color, floor }: { number: string; name: string; kind: string; color: string; floor: string }) {
  const {rates}=useCourtPricing()
  const rate=rates[number==='01'?1:2]
  return <article className="court-card"><div className={`court-illustration ${color}`}><span className="court-number-large">{number}</span><div className="mini-court"><i/><i/><b/></div><span className="court-pill"><span className="live-dot"/> READY TO PLAY</span></div><div className="court-card-copy"><div><small>{kind}</small><h3>{name}</h3><small>{floor} floor</small></div><span className="court-rate">₱{rate} <small>/ hr</small></span></div><div className="court-card-bottom"><span>Daily · 6 AM – 11 PM</span><BookLink to={`/book?court=${number === '01' ? 1 : 2}`} ariaLabel={`Book ${kind}`}><ArrowUpRight size={18}/></BookLink></div></article>
}
function Step({ n, icon, title, text }: { n: string; icon: React.ReactNode; title: string; text: string }) { return <article className="step"><div className="step-top"><span className="step-icon">{icon}</span><span>{n}</span></div><h3>{title}</h3><p>{text}</p></article> }
function AuthPage({ mode, user, authReady=true, adminState, retryAdminCheck }: { mode: 'login' | 'register' | 'reset'; user?:User|null; authReady?:boolean; adminState?:AdminState; retryAdminCheck?:()=>void }) {
  const navigate = useNavigate(); const routeLocation=useLocation(); const requestedNext=new URLSearchParams(routeLocation.search).get('next'); const postLoginPath=requestedNext&&(/^\/admin(?:[/?]|$)/).test(requestedNext)?requestedNext:'/admin'; const [busy,setBusy] = useState(false); const [message,setMessage] = useState(''); const [error,setError] = useState('')
  const title = mode === 'login' ? 'Admin sign in.' : mode === 'register' ? 'Come on in.' : 'Reset your password.'
  const isVerifiedAdmin=Boolean(user&&adminState?.userId===user.id&&(adminState.status==='admin'||adminState.status==='viewer'))
  const waitingForAdminCheck=Boolean(mode==='login'&&user&&(!authReady||adminState?.userId!==user.id||adminState.status==='checking'))
  useEffect(()=>{if(mode==='login'&&isVerifiedAdmin)navigate(adminState?.status==='viewer'?'/admin':postLoginPath,{replace:true})},[mode,isVerifiedAdmin,navigate,adminState?.status])
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); setError(''); setMessage(''); const data = Object.fromEntries(new FormData(e.currentTarget).entries()); if (!supabase) { setError('Connect Supabase in .env to enable accounts.'); return } setBusy(true)
    try { if(mode==='login'){const {data:authData,error}=await supabase.auth.signInWithPassword({email:String(data.email),password:String(data.password)}); if(error) throw error; const {data:profile,error:profileError}=await supabase.from('profiles').select('is_admin,is_booking_viewer').eq('id',authData.user.id).maybeSingle(); if(profileError)throw new Error('Your sign-in succeeded, but staff access could not be checked because the connection failed. Your session is still active; please retry.'); if(!profile?.is_admin&&!profile?.is_booking_viewer){await supabase.auth.signOut();throw new Error('This account does not have staff access.')} navigate(profile.is_admin?postLoginPath:'/admin',{replace:true})}
      else if(mode==='register'){if(data.password!==data.confirm) throw new Error('Passwords do not match.'); if(String(data.password).length<8) throw new Error('Use at least 8 characters for your password.'); const {error}=await supabase.auth.signUp({email:String(data.email),password:String(data.password),options:{data:{full_name:String(data.name)}}}); if(error) throw error; setMessage('Check your email to confirm your account, then come back to sign in.')}
      else {const {error}=await supabase.auth.resetPasswordForEmail(String(data.email),{redirectTo:`${location.origin}/login`}); if(error) throw error; setMessage('If an account exists for that email, a reset link is on its way.')} }
    catch(e){const message=e instanceof Error?e.message:'Something went wrong. Please try again.';setError(/failed to fetch|networkerror|load failed/i.test(message)?'Could not reach Supabase Auth. Check the project URL in .env, confirm the Supabase project is active, then restart the dev server.':message)} finally{setBusy(false)} }
  if(waitingForAdminCheck)return <div className="loading-page"><div className="spinner"/>Verifying administrator access…</div>
  if(mode==='login'&&user&&adminState?.userId===user.id&&adminState.status==='error')return <main className="auth-page"><div className="auth-card"><div className="auth-icon"><LockKeyhole/></div><span className="eyebrow">STAFF ACCESS · STAG BASE PICKLE HUB</span><h1>Checking access.</h1><p>Your session is still active, but we couldn’t verify the staff profile because of a connection problem.</p><button className="button button-dark full-button" type="button" onClick={retryAdminCheck}>Retry verification <ArrowRight size={16}/></button></div></main>
  return <main className="auth-page"><div className="auth-card"><div className="auth-icon"><img src="/stag-base-logo.png" alt="Stag Base logo"/></div><span className="eyebrow">{mode==='login'?'STAFF ACCESS · STAG BASE PICKLE HUB':'STAG BASE PICKLE HUB'}</span><h1>{mode==='login'?'Staff sign in.':title}</h1><p>{mode==='login'?'Sign in to view the court schedule or manage bookings.':mode==='register'?'Create an account to book your first game.':'We’ll email you a link to get back in.'}</p><form onSubmit={submit} className="form-stack">{mode==='register'&&<label>Full name<input name="name" placeholder="e.g. Alex Rivera" required autoComplete="name"/></label>}<label>Email address<input name="email" placeholder="you@example.com" type="email" required autoComplete="email"/></label>{mode!=='reset'&&<label>Password<input name="password" placeholder="At least 8 characters" type="password" required minLength={8} autoComplete={mode==='login'?'current-password':'new-password'}/></label>}{mode==='register'&&<label>Confirm password<input name="confirm" placeholder="Type it again" type="password" required minLength={8} autoComplete="new-password"/></label>}{error&&<div className="alert alert-error">{error}</div>}{message&&<div className="alert alert-success"><Check size={17}/>{message}</div>}<button className="button button-dark full-button" disabled={busy}>{busy?'Please wait…':mode==='login'?'Log in':mode==='register'?'Create account':'Send reset link'} <ArrowRight size={16}/></button></form><div className="auth-links">{mode==='login'?<Link to="/reset-password">Forgot password?</Link>:<span>Already have an account? <Link to="/login">Log in</Link></span>}</div><div className="auth-safe"><LockKeyhole size={14}/> Your account is protected with secure sign-in.</div></div></main>
}
function AuthGate({admin=false,next}:{admin?:boolean;next?:string}) { return <div className="auth-gate"><div className="auth-icon"><LockKeyhole/></div><h2>{admin?'Admin access required':'Log in to book a court'}</h2><p>{admin?'Sign in with an authorized administrator account.':'Create an account or sign in to see availability and manage your bookings.'}</p><Link className="button button-dark" to={`/login?next=${encodeURIComponent(next||(admin?'/admin':'/book'))}`}>Continue to log in <ArrowRight size={16}/></Link></div> }

function AdminRoute({user,adminState,retryAdminCheck}:{user:User|null;adminState:AdminState;retryAdminCheck:()=>void}){
 const location=useLocation()
 if(!user)return <AuthGate admin next={`${location.pathname}${location.search}`}/>
 if(adminState.userId!==user.id||adminState.status==='checking')return <div className="loading-page"><div className="spinner"/>Verifying administrator access…</div>
 if(adminState.status==='error')return <main className="page-shell"><div className="alert alert-error" role="alert">Could not verify administrator access because of a connection problem. Your session is still active.<button type="button" className="button button-outline" onClick={retryAdminCheck}>Retry</button></div></main>
 if(adminState.status==='viewer')return <ViewerBookingsDashboard/>
 if(adminState.status!=='admin')return <AuthGate admin/>
 return location.pathname==='/admin/reports'?<AdminReportsPage/>:<AdminDashboard/>
}

function ViewerBookingsDashboard(){
 const [date,setDate]=useState(localDate())
 const [rows,setRows]=useState<Booking[]>([])
 const [loading,setLoading]=useState(true)
 const [error,setError]=useState('')
 function moveDate(days:number){const next=new Date(`${date}T12:00:00`);next.setDate(next.getDate()+days);setDate(`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-${String(next.getDate()).padStart(2,'0')}`)}
 useEffect(()=>{if(!supabase)return;let active=true;const refresh=async()=>{const {data,error:loadError}=await supabase!.rpc('get_viewer_daily_bookings',{p_booking_date:date});if(!active)return;if(loadError){setError(loadError.message);setRows([])}else{setError('');setRows((data||[]) as Booking[])}setLoading(false)};setLoading(true);void refresh();const timer=window.setInterval(()=>void refresh(),15000);return()=>{active=false;window.clearInterval(timer)}},[date])
 return <main className="page-shell"><div className="page-intro"><span className="eyebrow">READ ONLY · COURT SCHEDULE</span><h1>Daily <em>bookings.</em></h1><p>View the court schedule and booking names. This account cannot make changes.</p></div>{error&&<div className="alert alert-error" role="alert">Could not load daily bookings: {error}</div>}{loading?<div className="loading-inline"><div className="spinner"/>Loading daily bookings…</div>:<AdminDaySchedule date={date} rows={rows} onDateChange={setDate} onMoveDate={moveDate} readOnly/>}</main>
}

function ThemedDatePickerButton({date,today,onDateChange,disabled}:{date:string;today:string;onDateChange:(date:string)=>void;disabled:boolean}) {
 const [open,setOpen]=useState(false)
 const [viewMonth,setViewMonth]=useState(()=>new Date(`${date}T12:00:00`))
 const rootRef=useRef<HTMLDivElement>(null)
 useEffect(()=>{setViewMonth(new Date(`${date}T12:00:00`))},[date])
 useEffect(()=>{if(!open)return;const key=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpen(false)};document.addEventListener('keydown',key);const previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',key);document.body.style.overflow=previousOverflow}},[open])
 const year=viewMonth.getFullYear(), month=viewMonth.getMonth()
 const monthStart=new Date(year,month,1)
 const firstDay=(monthStart.getDay()+6)%7
 const daysInMonth=new Date(year,month+1,0).getDate()
 const cells:Array<number|null>=[...Array.from({length:firstDay},()=>null),...Array.from({length:daysInMonth},(_,index)=>index+1)]
 const monthTitle=monthStart.toLocaleDateString('en-PH',{month:'long',year:'numeric'})
 const dateValue=(day:number)=>`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`
 const shiftMonth=(amount:number)=>setViewMonth(current=>new Date(current.getFullYear(),current.getMonth()+amount,1,12))
 return <><div className="booking-calendar-anchor" ref={rootRef}>
  <button type="button" className="booking-date-current" aria-label="Choose booking date" aria-expanded={open} onClick={()=>setOpen(value=>!value)} disabled={disabled}>{new Date(`${date}T12:00:00`).toLocaleDateString('en-PH',{weekday:'short',month:'short',day:'numeric'})}<CalendarDays size={13}/></button>
  </div>{open&&createPortal(<div className="booking-calendar-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)setOpen(false)}}><div className="booking-calendar-popover" role="dialog" aria-modal="true" aria-label="Choose booking date">
   <div className="booking-calendar-heading"><button type="button" aria-label="Previous month" disabled={year<Number(today.slice(0,4))||(year===Number(today.slice(0,4))&&month<=Number(today.slice(5,7))-1)} onClick={()=>shiftMonth(-1)}><ChevronLeft size={16}/></button><b>{monthTitle}</b><button type="button" aria-label="Next month" onClick={()=>shiftMonth(1)}><ChevronRight size={16}/></button><button type="button" aria-label="Close calendar" onClick={()=>setOpen(false)}><X size={16}/></button></div>
   <div className="booking-calendar-weekdays">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(day=><span key={day}>{day}</span>)}</div>
   <div className="booking-calendar-grid">{cells.map((day,index)=>day===null?<span key={`blank-${index}`}/>:<button type="button" key={day} className={`booking-calendar-day${date===dateValue(day)?' selected':''}${today===dateValue(day)?' today':''}`} disabled={disabled||dateValue(day)<today} onClick={()=>{onDateChange(dateValue(day));setOpen(false)}}>{day}</button>)}</div>
   <button type="button" className="booking-calendar-today" disabled={disabled||date===today} onClick={()=>{onDateChange(today);setViewMonth(new Date(`${today}T12:00:00`));setOpen(false)}}>Today</button>
  </div></div>,document.body)}</>
}


function BookingDatePicker({date,onDateChange,today,disabled,description='This date applies to both courts.',allowPast=false,headerActions,hideMonth=false}:{date:string;onDateChange:(date:string)=>void;today:string;disabled:boolean;description?:string;allowPast?:boolean;headerActions?:ReactNode;hideMonth?:boolean}){
 const datePickerRef=useRef<HTMLInputElement>(null)
 const rawDayDistance=Math.round((Date.parse(`${date}T12:00:00`)-Date.parse(`${today}T12:00:00`))/86400000)
 const dayDistance=allowPast?rawDayDistance:Math.max(0,rawDayDistance)
 const weekOffset=Math.floor(dayDistance/7)*7
 const days=Array.from({length:7},(_,i)=>localDate(weekOffset+i))
 const monthLabel=new Date(`${date}T12:00:00`).toLocaleDateString('en-PH',{month:'long',year:'numeric'})
 return <section className="availability-picker booking-shared-date-picker"><header className="availability-picker-head"><div><span className="picker-icon"><CalendarDays size={17}/></span><div><h3>Booking date</h3><p>{description}</p></div></div><div className="availability-date-controls">{!hideMonth&&<><button type="button" className="availability-month availability-month-button" onClick={()=>{const picker=document.querySelector<HTMLInputElement>('.booking-date-input-overlay')||datePickerRef.current;if(!picker)return;if(typeof picker.showPicker==='function')picker.showPicker();else picker.click()}} disabled={disabled}>{monthLabel}<CalendarDays size={14}/></button><input ref={datePickerRef} className="availability-date-input" type="date" aria-label="Choose booking date" value={date} min={allowPast?undefined:today} disabled={disabled} onChange={e=>{if(e.target.value)onDateChange(e.target.value)}}/></>}{headerActions}</div></header><div className="availability-days">{!headerActions&&<button className="availability-arrow" aria-label="Show previous dates" disabled={(!allowPast&&weekOffset<=0)||disabled} onClick={()=>onDateChange(allowPast?localDate(weekOffset-7):localDate(Math.max(0,weekOffset-7)))}>‹</button>}{days.map(day=><button key={day} className={`availability-day${date===day?' active':''}`} disabled={disabled} onClick={()=>onDateChange(day)}><small>{day===today?'Today':new Date(`${day}T12:00:00`).toLocaleDateString('en-PH',{weekday:'short'})}</small><b>{new Date(`${day}T12:00:00`).getDate()}</b></button>)}{!headerActions&&<button className="availability-arrow" aria-label="Show later dates" disabled={disabled} onClick={()=>onDateChange(localDate(weekOffset+7))}>›</button>}</div></section>
}

function PlayTimePicker({date,court,slots,selectedSlots,slotStatuses,today,onSelectSlot,disabled}:{date:string;court:number;slots:number[];selectedSlots:number[];slotStatuses:Record<number,string>;today:string;onSelectSlot:(hour:number)=>void;disabled:boolean}) {
 const {rates}=useCourtPricing()
 const timeParts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Manila',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(part=>[part.type,part.value]))
 const currentHour=Number(timeParts.hour),currentMinute=Number(timeParts.minute),currentSecond=Number(timeParts.second)
 const isPast=(hour:number)=>date===today&&(hour<currentHour||(hour===currentHour&&(currentMinute>0||currentSecond>0)))
 return <section className="availability-picker dual-court-picker-card"><header className="availability-picker-head"><div><span className="picker-icon"><CalendarDays size={17}/></span><div><h3>Court {court} - {court===1?'The Basic':'The Pro'}</h3><p>{court===1?'Rubberized':'Silica'} floor · ₱{rates[court]}/hour</p></div></div></header><div className="availability-table booking-hour-grid">{slots.map(hour=>{const status=slotStatuses[hour];const selected=selectedSlots.includes(hour);const past=isPast(hour);const unavailable=Boolean(status)||past;const state=status==='pending'?'On hold':status==='booked'?'Booked':status==='maintenance'?'Maintenance':past?'Unavailable':selected?'Selected':`₱${rates[court]}`;return <button key={hour} aria-label={`${hourLabel(hour)} to ${hourLabel(hour+1)}, ${status==='pending'?'On hold':status==='booked'?'Booked':status==='maintenance'?'Maintenance':past?'Unavailable':selected?'Selected':`Available for ₱${rates[court]}`}`} className={'availability-slot booking-hour-tile' + (selected ? ' selected' : '') + (status ? ' ' + status : past ? ' unavailable' : '')} disabled={disabled||unavailable} onClick={()=>onSelectSlot(hour)}><span className="booking-hour-time"><span className="booking-time-wide">{hourLabel(hour)} – {hourLabel(hour+1)}</span><span className="booking-time-compact">{compactHourLabel(hour)} - {compactHourLabel(hour+1)}</span></span><span className="booking-hour-state">{state}</span></button>})}</div><div className="availability-legend"><span><i className="legend-available"/> Available</span><span><i className="legend-booked"/> Booked</span><span><i className="legend-pending"/> On hold</span><span><i className="legend-maintenance"/> Maintenance</span><span><i className="legend-selected"/> Selected</span></div></section>
}

function BookingPage() {
 const navigate=useNavigate()
 const {rates}=useCourtPricing()
 const [date,setDate]=useState(localDate())
 const [selected,setSelected]=useState<Record<number,number[]>>({1:[],2:[]})
 const [statuses,setStatuses]=useState<Record<number,Record<number,string>>>({1:{},2:{}})
 const [busy,setBusy]=useState(false)
 const [contact,setContact]=useState({name:'',email:'',phone:''})
 const [agreed,setAgreed]=useState(false)
 const [showSummary,setShowSummary]=useState(false)
 const [error,setError]=useState('')
 const today=localDate()
 const slots=useMemo(()=>Array.from({length:17},(_,i)=>i+6),[])
 const counts:Record<number,number>={1:selected[1].length,2:selected[2].length}
 const total=counts[1]*rates[1]+counts[2]*rates[2]
 const selectedCourtCount=[1,2].filter(court=>counts[court]>0).length
 const emailIsValid=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(contact.email.trim())
 const phoneDigits=contact.phone.replace(/\D/g,'')
 const phoneIsValid=phoneDigits.length===11

 useEffect(()=>{if(!showSummary)return;const close=(event:KeyboardEvent)=>{if(event.key==='Escape')setShowSummary(false)};const previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';document.addEventListener('keydown',close);return()=>{document.body.style.overflow=previousOverflow;document.removeEventListener('keydown',close)}},[showSummary])

 useEffect(()=>{
   setSelected({1:[],2:[]})
   if(!supabase){setStatuses({1:{},2:{}});return}
   let active=true
   let refreshTimer:number|undefined
   let refreshing=false
   let refreshRequested=false
   const refresh=async()=>{
     if(refreshing){refreshRequested=true;return}
     refreshing=true
     try{
       const results=await Promise.all([1,2].map(court=>supabase!.rpc('get_slot_availability',{p_court_id:court,p_booking_date:date})))
       if(!active)return
       const next:Record<number,Record<number,string>>={1:{},2:{}}
       results.forEach((result,index)=>{if(!result.error)next[index+1]=Object.fromEntries((result.data||[]).map((row:{hour:number;slot_status:string})=>[row.hour,row.slot_status]))})
       setStatuses(next)
     }finally{
       refreshing=false
       if(active&&refreshRequested){refreshRequested=false;window.setTimeout(()=>void refresh(),0)}
     }
   }
   const scheduleRefresh=()=>{if(refreshTimer!==undefined)window.clearTimeout(refreshTimer);refreshTimer=window.setTimeout(()=>void refresh(),200)}
   const channel=supabase.channel(`customer-availability-${date}`)
     .on('postgres_changes',{event:'*',schema:'public',table:'availability_signals',filter:`booking_date=eq.${date}`},scheduleRefresh)
     .subscribe(status=>{if(status==='SUBSCRIBED')void refresh()})
   void refresh()
   const timer=window.setInterval(()=>void refresh(),15000)
   return()=>{active=false;window.clearInterval(timer);if(refreshTimer!==undefined)window.clearTimeout(refreshTimer);void supabase!.removeChannel(channel)}
 },[date])

 function selectSlot(court:number,hour:number){setError('');setSelected(current=>({...current,[court]:current[court].includes(hour)?current[court].filter(value=>value!==hour):[...current[court],hour].sort((a,b)=>a-b)}))}
 function moveBookingDate(days:number){const next=new Date(`${date}T12:00:00`);next.setDate(next.getDate()+days);const nextDate=`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-${String(next.getDate()).padStart(2,'0')}`;if(nextDate>=today)setDate(nextDate)}
 async function book(){
   setError('')
   if(!contact.name.trim()){setError('Enter your name.');return}
   if(!contact.email.trim()||!emailIsValid){setError('Enter a valid email address, such as you@example.com.');return}
   if(!phoneIsValid){setError('Enter a valid phone number with exactly 11 digits.');return}
   if(!supabase){setError('Connect Supabase before placing a reservation.');return}
   const courtSelections=[1,2].filter(court=>selected[court].length>0).map(court=>({court_id:court,hours:selected[court]}))
   if(!courtSelections.length)return
   setBusy(true)
   const {data,error:rpcError}=await supabase.rpc('create_guest_booking_multi',{p_booking_date:date,p_court_selections:courtSelections,p_customer_name:contact.name.trim(),p_customer_email:contact.email.trim(),p_customer_phone:phoneDigits,p_payment_method:'online'})
   if(rpcError){setBusy(false);const detail=rpcError.message.toLowerCase().includes('overlap')||rpcError.message.toLowerCase().includes('just taken')?'One of those times was just taken. Check availability and try again.':rpcError.message;setError(detail);return}
   const created=data as {id:string;reference:string;total_price:number;access_token:string}
   sessionStorage.setItem(`guest_booking_token:${created.id}`,created.access_token)
   saveActiveGuestHold(created.id,created.access_token)
   setBusy(false)
   navigate(`/booking/${created.id}`)
 }

 return <main className="page-shell booking-layout"><div className="page-intro"><span className="eyebrow">MAKE IT A RALLY DAY</span><h1>Book your <em>courts.</em></h1><p>Choose times on either court, or both, in one reservation.</p></div><div className="booking-grid booking-grid-dual"><section className="booking-form"><div className="form-section-title"><span>01</span><div><h3>Choose your play times</h3><p>Select available hours for either or both courts. Gaps are allowed.</p></div></div><div className="dual-court-picker"><BookingDatePicker date={date} onDateChange={setDate} today={today} disabled={busy} hideMonth headerActions={<div className="booking-date-actions"><button type="button" aria-label="Previous day" disabled={busy||date<=today} onClick={()=>moveBookingDate(-1)}><ChevronLeft size={15}/></button><ThemedDatePickerButton date={date} today={today} onDateChange={setDate} disabled={busy}/><button type="button" aria-label="Next day" disabled={busy} onClick={()=>moveBookingDate(1)}><ChevronRight size={15}/></button><button type="button" className="booking-date-today" disabled={busy||date===today} onClick={()=>setDate(today)}>Today</button></div>}/><div className="dual-court-picker-courts">{[1,2].map(court=><PlayTimePicker key={court} date={date} court={court} slots={slots} selectedSlots={selected[court]} slotStatuses={statuses[court]} today={today} onSelectSlot={hour=>selectSlot(court,hour)} disabled={busy}/>)}</div></div></section>{showSummary&&createPortal(<div className="booking-summary-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)setShowSummary(false)}}><aside className="booking-summary booking-summary-modal" onMouseDown={event=>event.stopPropagation()}><button type="button" className="booking-summary-close" aria-label="Close booking summary" onClick={()=>setShowSummary(false)}><X size={18}/></button><span className="eyebrow">YOUR GAME PLAN</span><h3>Booking summary</h3><div className="summary-line"><span>Date</span><b>{new Date(`${date}T12:00:00`).toLocaleDateString('en-PH',{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</b></div>{[1,2].filter(court=>counts[court]>0).map(court=><div className="dual-booking-summary" key={court}><b>{court===1?'The Basic · Court 1':'The Pro · Court 2'}</b><div className="court-summary-row"><span>Court Time:</span><strong>{slotRanges(selected[court])}</strong></div><div className="court-summary-row"><span>Court Fee:</span><strong>₱{rates[court]} × {counts[court]} hour{counts[court]===1?'':'s'}</strong></div><div className="court-summary-row court-summary-subtotal"><span>Total:</span><strong>{peso(counts[court]*rates[court])}</strong></div></div>)}{total>0&&<div className="summary-total"><span>Total due</span><b>{peso(total)}</b></div>}<div className="guest-contact-fields"><h4>Booking contact</h4><p>We will email your confirmation after the admin approves your bookings.</p><label>Full name<input autoComplete="name" placeholder="e.g. Alex Rivera" value={contact.name} onChange={e=>setContact({...contact,name:e.target.value})} required maxLength={120}/></label><label>Email address<input type="email" autoComplete="email" placeholder="you@example.com" value={contact.email} onChange={e=>setContact({...contact,email:e.target.value})} required maxLength={254}/></label><label>Phone number<input type="tel" autoComplete="tel" placeholder="09XX XXX XXXX" value={contact.phone} onChange={e=>setContact({...contact,phone:e.target.value})} required maxLength={32}/></label></div><label className="booking-agreement"><input type="checkbox" checked={agreed} onChange={e=>setAgreed(e.target.checked)}/><span><b>I agree</b> that all booking payments are final and non-refundable, my payment details and receipt must be correct, and an invalid payment may release this reservation.</span></label>{error&&<div className="alert alert-error" role="alert">{error}</div>}<button className="button button-dark full-button" onClick={book} disabled={busy||!total||!contact.name.trim()||!contact.email.trim()||!contact.phone.trim()||!agreed}>{busy?'Reserving selected times…':'Reserve selected times'} <ArrowRight size={16}/></button><p className="summary-note"><ShieldCheck size={14}/> Reserve your selected times to see the GCash QR code and number. Each reservation is held for 10 minutes. Payment proof is optional; you can submit without paying now and pay cash later. If you do upload proof, the admin will review the amount. If you take no action, the hold is cancelled and the times become available.</p></aside></div>,document.body)}</div>{selectedCourtCount>0&&<div className="booking-selection-snackbar"><div className="booking-selection-copy"><b>{selectedCourtCount} court{selectedCourtCount===1?"":"s"} selected</b><div>{[1,2].filter(court=>counts[court]>0).map(court=><span key={court}>{court===1?"Court 1":"Court 2"} · {peso(counts[court]*rates[court])} · {counts[court]} hour{counts[court]===1?"":"s"}</span>)}</div></div><div className="booking-selection-actions"><button type="button" className="button button-dark" onClick={()=>setShowSummary(true)}>Book now <ArrowRight size={16}/></button><button type="button" className="booking-clear-selection" onClick={()=>setSelected({1:[],2:[]})}>Clear selection</button></div></div>}</main>
}

function Dashboard({user}:{user:User}) {
 const [bookings,setBookings]=useState<Booking[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [uploading,setUploading]=useState<string|null>(null);const [notice,setNotice]=useState('')
 const [paymentInstructions,setPaymentInstructions]=useState<Record<string,string>>({})
 async function load(){if(!supabase)return;setLoading(true);await supabase.rpc('expire_booking_holds');const {data,error}=await supabase.from('bookings').select('*,payments(status,rejection_reason,submitted_at)').eq('user_id',user.id).in('status',['held','pending','confirmed','rejected','cancelled','completed']).order('booking_date',{ascending:false}).order('start_hour',{ascending:false});if(error)setError(error.message);else setBookings((data||[]) as Booking[]);setLoading(false)}
 useEffect(()=>{void load()},[user.id])

 useEffect(()=>{if(supabase)supabase.from('app_settings').select('key,value').eq('key','payment_instructions').maybeSingle().then(({data})=>setPaymentInstructions(data?.value||{}))},[])
 async function upload(booking:Booking,file?:File){if(!file||!supabase)return;setError('');if(!['image/jpeg','image/png','image/webp'].includes(file.type)){setError('Use a JPG, PNG, or WebP image.');return}if(file.size>5*1024*1024){setError('Image must be 5 MB or smaller.');return}setUploading(booking.id);const path=`${user.id}/${booking.id}/${crypto.randomUUID()}-${file.name}`;const {error:upErr}=await supabase.storage.from('payment-proofs').upload(path,file,{contentType:file.type,upsert:false});if(upErr){setError(upErr.message);setUploading(null);return}const {error:rowErr}=await supabase.from('payments').insert({booking_id:booking.id,proof_path:path,amount:booking.total_price});if(rowErr)setError(rowErr.message);else setNotice('Payment proof submitted for review.');setUploading(null);void load()}
 const today=localDate(); const next=bookings.filter(b=>['pending','confirmed'].includes(b.status)&&b.booking_date>=today).length
 return <main className="page-shell"><div className="dashboard-welcome"><div><span className="eyebrow">STAG BASE MEMBER ACCOUNT</span><h1>Hey, {user.user_metadata?.full_name?.split(' ')[0]||'there'} <span>✳</span></h1><p>Ready for your next game?</p></div><Link className="button button-dark" to="/book">Book a court <ArrowRight size={16}/></Link></div><div className="dashboard-stats"><div><small>UPCOMING GAMES</small><b>{next}</b></div><div><small>BOOKINGS TOTAL</small><b>{bookings.length}</b></div><div><small>YOUR CLUB</small><b>Stag Base</b></div></div>{(paymentInstructions.gcash_number||paymentInstructions.bank_account_number)&&<div className="payment-instructions"><CreditCard/><div><b>Payment instructions</b><p>{paymentInstructions.gcash_number&&<>GCash: {paymentInstructions.gcash_name} · {paymentInstructions.gcash_number}<br/></>}{paymentInstructions.bank_account_number&&<>Bank transfer: {paymentInstructions.bank_name} · {paymentInstructions.bank_account_name} · {paymentInstructions.bank_account_number}</>}</p><small>Use your booking reference as the payment note, then upload your screenshot with that booking.</small></div></div>}<div className="dashboard-heading"><div><span className="eyebrow">YOUR GAME HISTORY</span><h2>My bookings</h2></div><BookLink to="/book">Find a time <ArrowRight size={15}/></BookLink></div>{error&&<div className="alert alert-error">{error}</div>}{notice&&<div className="alert alert-success"><Check size={17}/>{notice}</div>}{loading?<div className="loading-inline"><div className="spinner"/>Loading your bookings…</div>:bookings.length===0?<div className="empty-card"><CalendarDays size={26}/><h3>No bookings yet</h3><p>Your next good game starts with a court reservation.</p><BookLink className="button button-dark" to="/book">Book your first court <ArrowRight size={16}/></BookLink></div>:<div className="booking-list">{bookings.map(b=><BookingRow key={b.id} booking={b} onUpload={upload} uploading={uploading===b.id}/>)}</div>}</main>
}
function BookingRow({booking:b,onUpload,uploading,adminMode=false,onViewDetails,onAdminCancel}:{booking:Booking;onUpload:(b:Booking,f?:File)=>void;uploading:boolean;adminMode?:boolean;onViewDetails?:()=>void;onAdminCancel?:()=>void}){const canUpload=b.status==='pending'&&['unpaid','rejected'].includes(b.payment_status);const rejection=[...(b.payments||[])].filter(p=>p.status==='rejected').sort((a,c)=>c.submitted_at.localeCompare(a.submitted_at))[0]?.rejection_reason;const statusLabel=b.status==='held'?'On hold':b.status==='pending'?'On hold':b.status==='confirmed'||b.status==='completed'?'Booked':b.status==='rejected'?'Rejected':b.status==='cancelled'?'Cancelled':'Payment Required';const statusClass=b.status==='held'?'payment-required':b.status==='pending'?'waiting-confirmation':b.status==='confirmed'||b.status==='completed'?'approved':b.status;const courtHours=bookingCourtHours(b);return <article className={`booking-row${adminMode?' admin-booking-row':''}`}><div className="booking-date-block"><b>{new Date(`${b.booking_date}T12:00:00`).toLocaleDateString('en',{day:'2-digit'})}</b><small>{new Date(`${b.booking_date}T12:00:00`).toLocaleDateString('en',{month:'short'}).toUpperCase()}</small></div><div className="booking-info"><span className="eyebrow">{bookingCourtsLabel(b)} · {b.reference}</span><h3>{bookingTimeLabel(b)}</h3><p>{new Date(`${b.booking_date}T12:00:00`).toLocaleDateString('en-PH',{weekday:'long',month:'long',day:'numeric',year:'numeric'})} · {courtHours} court hour{courtHours===1?'':'s'}</p>{adminMode&&<p className="booking-customer-name">Customer: <b>{b.customer_name||b.profiles?.full_name||'Rally customer'}</b></p>}{!adminMode&&<Link className="view-details-link" to={`/booking/${b.id}`}>View details <ArrowRight size={13}/></Link>}</div><div className="booking-price"><b>{peso(b.total_price)}</b><span className={`badge badge-${statusClass}`}>{statusLabel}</span>{b.status==='rejected'&&rejection&&<small className="rejection-reason">{rejection}</small>}{canUpload&&!adminMode&&<label className="upload-link">{uploading?'Uploading…':b.payment_status==='rejected'?'Replace proof':'Upload proof'}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={uploading} onChange={e=>onUpload(b,e.target.files?.[0])}/></label>}{adminMode&&<div className="admin-card-actions"><button className="admin-view-link" onClick={onViewDetails}>View details <ArrowRight size={13}/></button>{!['cancelled','completed','rejected'].includes(b.status)&&<button className="cancel-link" onClick={onAdminCancel}>Cancel</button>}</div>}</div></article>}

function BookingDetailsPage({user}: {user:User|null}) {
 const {id=''}=useParams();const navigate=useNavigate();const guestTokenFromUrl=id?new URLSearchParams(window.location.hash.slice(1)).get('access_token')||new URLSearchParams(window.location.search).get('access_token'):null;const savedActiveHold=readActiveGuestHold();const guestToken=id?guestTokenFromUrl||sessionStorage.getItem(`guest_booking_token:${id}`)||(savedActiveHold?.id===id?savedActiveHold.token:null):null;const [booking,setBooking]=useState<any>(null);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [uploadBusy,setUploadBusy]=useState(false);const [preview,setPreview]=useState<string|null>(null);const [fileName,setFileName]=useState('');const [error,setError]=useState('');const [message,setMessage]=useState('');const [instructions,setInstructions]=useState<Record<string,string>>({});const [cancellationHours,setCancellationHours]=useState(12);const [cancelledByUser,setCancelledByUser]=useState(false);const [copyMessage,setCopyMessage]=useState('' )
 useEffect(()=>{if(!id||!guestTokenFromUrl)return;sessionStorage.setItem(`guest_booking_token:${id}`,guestTokenFromUrl);const currentUrl=new URL(window.location.href);currentUrl.searchParams.delete('access_token');currentUrl.hash='';window.history.replaceState(window.history.state,'',`${currentUrl.pathname}${currentUrl.search}`)},[id,guestTokenFromUrl])
 useEffect(()=>{if(!id||!guestToken||!booking)return;if(booking.status==='held'&&new Date(booking.hold_expires_at).getTime()>Date.now())saveActiveGuestHold(id,guestToken);else clearActiveGuestHold(id)},[id,guestToken,booking?.status,booking?.hold_expires_at])
 async function load(){if(!supabase||!id)return;if(guestToken){const {data,error}=await supabase.rpc('get_guest_booking',{p_booking_id:id,p_token:guestToken});if(error)setError(error.message);else{setBooking(data);setCancelledByUser(Boolean(data.cancelled_by_customer))}}else if(user){await supabase.rpc('expire_booking_holds');const {data,error}=await supabase.from('bookings').select('*,payments(id,status,rejection_reason,submitted_at,proof_path)').eq('id',id).single();if(error)setError(error.message);else{setBooking(data);if(data.status==='cancelled'){const {data:audit}=await supabase.from('audit_logs').select('id').eq('entity_type','booking').eq('entity_id',id).eq('action','customer_booking_cancelled').limit(1);setCancelledByUser(Boolean(audit?.length))}else setCancelledByUser(false)}}else setError('This booking link is unavailable. Reopen the booking from the device where you made it.');setLoading(false)}
 useEffect(()=>{void load();if(supabase){supabase.from('app_settings').select('value').eq('key','payment_instructions').maybeSingle().then(({data})=>setInstructions(data?.value||{}));supabase.from('app_settings').select('value').eq('key','booking_policy').maybeSingle().then(({data})=>setCancellationHours(Number(data?.value?.cancellation_hours)||12))}},[id])

 // Guest booking links cannot rely on authenticated realtime subscriptions, so
 // refresh the booking status while this details page remains open.
 useEffect(()=>{const timer=window.setInterval(()=>{void load()},5000);return()=>window.clearInterval(timer)},[id])


 useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview)},[preview])
 async function upload(file?:File){if(!file||!supabase||!booking)return;setError('');if(!['image/jpeg','image/png','image/webp'].includes(file.type)){setError('Upload a JPG, PNG, or WebP image.');return}if(file.size>5*1024*1024){setError('Payment screenshot must be 5 MB or smaller.');return}if(preview)URL.revokeObjectURL(preview);setPreview(URL.createObjectURL(file));setFileName(file.name);setUploadBusy(true);const path=guestToken?`${booking.id}/${guestToken}/${crypto.randomUUID()}-${file.name}`:`${user!.id}/${booking.id}/${crypto.randomUUID()}-${file.name}`;const {error:uploadError}=await supabase.storage.from('payment-proofs').upload(path,file,{contentType:file.type,upsert:false});if(uploadError){setError(uploadError.message);setUploadBusy(false);return}if(guestToken){const {error}=await supabase.rpc('submit_guest_payment_proof',{p_booking_id:booking.id,p_token:guestToken,p_proof_path:path});if(error){setError(error.message);setUploadBusy(false);return}}else{const {error}=await supabase.from('payments').insert({booking_id:booking.id,proof_path:path,amount:booking.total_price});if(error){setError(error.message);setUploadBusy(false);return}}setUploadBusy(false);await load()}
 async function removeProof(){if(!supabase||!booking||!guestToken||!latestProof)return;setBusy(true);setError('');const {data:proofPath,error}=await supabase.rpc('remove_guest_payment_proof',{p_booking_id:booking.id,p_token:guestToken,p_payment_id:latestProof.id});if(error){setError(error.message);setBusy(false);return}if(preview)URL.revokeObjectURL(preview);setPreview(null);setFileName('');const {error:storageError}=await supabase.storage.from('payment-proofs').remove([proofPath]);await load();setBusy(false);setMessage(storageError?'Screenshot removed from the booking. Please upload the correct image.':'Screenshot removed. Upload the correct payment image or submit the booking when ready.')}
 async function confirm(){if(!supabase||!booking)return;setBusy(true);setError('');const {error}=guestToken?await supabase.rpc('confirm_guest_booking_request',{p_booking_id:booking.id,p_token:guestToken}):await supabase.rpc('confirm_booking_request',{p_booking_id:booking.id});setBusy(false);if(error){setError(error.message);return}clearActiveGuestHold(id);if(guestToken){setMessage('Your booking has been sent to the admin for confirmation.');await load()}else navigate('/dashboard')}
 async function cancelBooking(){if(!supabase||!booking||!window.confirm(booking.status==='held'?'Cancel this unpaid reservation and release the hold?':`Cancel booking ${booking.reference}? Cancellations are allowed ${cancellationHours} hours before the start time.`))return;setBusy(true);setError('');const {error}=guestToken?await supabase.rpc('cancel_guest_booking',{p_booking_id:booking.id,p_token:guestToken}):await supabase.rpc('cancel_my_booking',{p_booking_id:booking.id});setBusy(false);if(error){setError(error.message);return}clearActiveGuestHold(id);if(guestToken)await load();else navigate('/dashboard')}
 async function copyBookingDetails(){if(!booking)return;const details=[`Stag Base Pickle Hub booking ${booking.reference}`,`Date: ${dateLabel}`,...bookingSelections(booking).map(selection=>`${courtLabel(selection.court_id)}: ${slotRanges(selection.hours)}`),`Status: ${statusLabel}`,`Total: ${peso(booking.total_price)}`,`Booking link: ${guestToken?`${window.location.origin}/booking/${booking.id}#access_token=${encodeURIComponent(guestToken)}`:window.location.href}`].join('\n');try{await navigator.clipboard.writeText(details);setCopyMessage('Booking details copied.');window.setTimeout(()=>setCopyMessage(''),2500)}catch{setCopyMessage('Clipboard access is unavailable.')}}
 if(loading)return <div className="loading-inline"><div className="spinner"/>Loading booking details…</div>
 if(!booking)return <main className="page-shell"><div className="alert alert-error">{error||'Booking not found.'}</div></main>
 const hasProof=booking.payment_status==='proof_submitted'||(booking.payments||[]).some((p:any)=>p.status==='proof_submitted');const statusLabel=booking.status==='held'?'On hold':booking.status==='pending'?'On hold':booking.status==='confirmed'||booking.status==='completed'?'Booked':booking.status==='rejected'?'Rejected':booking.status==='cancelled'?'Cancelled':'Payment Required';const statusClass=booking.status==='held'?'payment-required':booking.status==='pending'?'waiting-confirmation':booking.status==='confirmed'||booking.status==='completed'?'approved':booking.status;const dateLabel=new Date(`${booking.booking_date}T12:00:00`).toLocaleDateString('en-PH',{weekday:'long',month:'long',day:'numeric',year:'numeric'});const bookedAt=new Date(booking.created_at).toLocaleString('en-PH',{timeZone:'Asia/Manila',weekday:'long',month:'long',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});const activeHold=booking.status==='held';const latestProof=[...(booking.payments||[])].sort((a:any,b:any)=>b.submitted_at.localeCompare(a.submitted_at))[0];const firstReservedHour=Math.min(...bookingSelections(booking).flatMap(selection=>selection.hours));const canCancel=(guestToken&&activeHold)||(['pending','confirmed'].includes(booking.status)&&(new Date(`${booking.booking_date}T${String(firstReservedHour).padStart(2,'0')}:00:00+08:00`).getTime()-Date.now()>cancellationHours*60*60*1000))
 return <main className="details-page-backdrop"><div className="details-page-panel">{activeHold&&<HoldExpiryNotice booking={booking} variant="modal" onExpired={async()=>{setMessage("The 10-minute hold expired. This time is available again. Please start a new booking.");clearActiveGuestHold(id);await load()}}/>}<div className="page-intro"><span className="eyebrow">BOOKING DETAILS · {booking.reference}</span><h1>Your court <em>reservation.</em></h1><p>Review your game time and payment status.</p></div><div className="booking-copy-reminder"><div><b>Keep your booking details</b><span>Copy them so you can check your reservation later.</span></div><button type="button" className="copy-booking-details" onClick={copyBookingDetails}><Copy size={15}/>{copyMessage||'Copy booking details'}</button></div><section className="details-card"><div className="details-top"><div className="details-primary-lines"><p className="details-primary-date">{dateLabel}</p>{bookingSelections(booking).map(selection=><p className="details-primary-time" key={selection.court_id}><b>{courtLabel(selection.court_id)}:</b> {slotRanges(selection.hours)}</p>)}</div><span className={`badge badge-${statusClass}`}>{statusLabel}</span></div><div className="details-facts"><div><small>BOOKED ON</small><b>{bookedAt}</b></div><div><small>Play time:</small><b>{bookingCourtHours(booking)} court hour{bookingCourtHours(booking)===1?'':'s'}</b></div><div><small>TOTAL DUE</small><b>{peso(booking.total_price)}</b></div></div>{activeHold?<>{error&&<div className="alert alert-error">{error}</div>}<><div className="hold-payment-info"><h3>GCash / InstaPay details</h3><GcashNumber/><img className="gcash-payment-qr" src="/gcash-payment-qr-code.png" alt="GCash and InstaPay payment QR code"/><a className="qr-download-link" href="/gcash-payment-qr-code.png" download="Stag-Base-GCash-QR.png"><Download size={14}/> Save QR image</a><p className="payment-transfer-note">Scan to send {peso(booking.total_price)}. Transfer fees may apply.</p><p className="payment-minimum-note">Pay at least 50% of the total booking amount.</p><a className="gcash-details-link" href="/gcash-payment-qr.png" target="_blank" rel="noreferrer">View full GCash / InstaPay details</a>{instructions.gcash_number&&<p>GCash: <b>M* AN***A S.</b> · 09052692785</p>}{instructions.bank_account_number&&<p>Bank: <b>{instructions.bank_name}</b> · {instructions.bank_account_name} · {instructions.bank_account_number}</p>}<small>Upload proof if you paid online, or book now and pay cash at the court.</small></div><h3 className="payment-step-title">Upload a payment screenshot</h3>{!hasProof&&<label className="button button-outline proof-upload-button">{uploadBusy?'Uploading screenshot…':'Choose screenshot'}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={uploadBusy} onChange={e=>upload(e.target.files?.[0])}/></label>}{(preview||(guestToken&&hasProof))&&<div className="proof-preview">{preview&&<img src={preview} alt="Payment screenshot preview"/>}<div><b>{uploadBusy?'Uploading screenshot…':'Screenshot uploaded'}</b><small>{fileName||latestProof?.proof_path?.split('/').pop()||'Payment screenshot'}</small></div>{guestToken&&hasProof&&<button type="button" className="proof-remove-button" aria-label="Remove uploaded screenshot" title="Remove uploaded screenshot" disabled={busy||uploadBusy} onClick={removeProof}><Trash2 size={17}/></button>}</div>}{hasProof&&<div className="alert alert-success proof-ready"><Check size={16}/> Screenshot uploaded. Press Book now to send your booking and proof for admin review.</div>}</>{error&& !activeHold&&<div className="alert alert-error">{error}</div>}<button className="button button-dark full-button" onClick={confirm} disabled={busy||uploadBusy}>{busy?'Submitting…':'Book now'} <ArrowRight size={16}/></button></>:<div className="details-status">{message&&<p>{message}</p>}{cancelledByUser&&<p>Cancelled Booking</p>}{!cancelledByUser&&booking.status==='cancelled'&&booking.payment_status==='unpaid'&&<p>Payment Status: <b>Unpaid</b></p>}{booking.status==='rejected'&&latestProof?.rejection_reason&&<p className="rejection-reason">{latestProof.rejection_reason}</p>}{booking.status==='pending'&&<p>Your booking is On hold until the admin confirms it.</p>}</div>}{(canCancel||activeHold)&&<button className="cancel-link details-cancel" disabled={busy} onClick={cancelBooking}>{busy?'Cancelling…':'Cancel booking'}</button>}{!['held','pending'].includes(booking.status)&&<Link className="button button-outline full-button details-back-booking" to="/book">Back to booking <ArrowRight size={15}/></Link>}</section></div></main>
}

function BookingGroupDetailsPage(){
 const {groupId=''}=useParams()
 const [bookings,setBookings]=useState<any[]>([])
 const [loading,setLoading]=useState(true)
 const [busy,setBusy]=useState(false)
 const [error,setError]=useState('')
 const [message,setMessage]=useState('')
 const ids=useMemo(()=>{try{return JSON.parse(sessionStorage.getItem(`guest_booking_group:${groupId}`)||'[]') as string[]}catch{return []}},[groupId])
 async function load(){
   if(!supabase||!ids.length){setLoading(false);setError('This grouped booking link is unavailable. Reopen it on the device where you made the reservation.');return}
   const results=await Promise.all(ids.map(id=>{const token=sessionStorage.getItem(`guest_booking_token:${id}`);return token?supabase!.rpc('get_guest_booking',{p_booking_id:id,p_token:token}):Promise.resolve({data:null,error:new Error('Booking access token is missing.')})}))
   const failedError=results.find(result=>result.error)?.error
   if(failedError)setError(failedError.message)
   else setBookings(results.map(result=>result.data).filter(Boolean).sort((a,b)=>a.court_id-b.court_id))
   setLoading(false)
 }
 useEffect(()=>{void load()},[groupId])
 const total=bookings.reduce((sum,booking)=>sum+Number(booking.total_price||0),0)
 const held=bookings.filter(booking=>booking.status==='held')
 async function submit(){
   if(!supabase||held.length!==bookings.length)return
   setBusy(true);setError('');setMessage('')
   const payload=bookings.map(booking=>({booking_id:booking.id,token:sessionStorage.getItem(`guest_booking_token:${booking.id}`)}))
   const {error:submitError}=await supabase.rpc('confirm_guest_booking_batch',{p_bookings:payload})
   setBusy(false)
   if(submitError){setError(submitError.message.includes('confirm_guest_booking_batch')?'Apply supabase/migrations/202611160004_batch_guest_booking_submission.sql to enable the combined submit, then retry.':submitError.message);return}
   setMessage('Both court reservations are on hold for admin confirmation. A confirmation email will be sent after the admin confirms each booking.')
   await load()
 }
 async function cancelAll(){
   if(!supabase||!held.length||!window.confirm('Cancel both court holds and release all selected times?'))return
   setBusy(true);setError('')
   const results=await Promise.all(held.map(booking=>supabase!.rpc('cancel_guest_booking',{p_booking_id:booking.id,p_token:sessionStorage.getItem(`guest_booking_token:${booking.id}`)})))
   const failedError=results.find(result=>result.error)?.error
   setBusy(false)
   if(failedError){setError(failedError.message);return}
   setMessage('Both court holds have been cancelled and released.')
   await load()
 }
 if(loading)return <div className="loading-inline"><div className="spinner"/>Loading grouped reservation…</div>
 return <main className="page-shell details-layout"><div className="page-intro"><span className="eyebrow">TWO COURTS · ONE RESERVATION</span><h1>Your game <em>plan.</em></h1><p>Review both court selections, then send them together for admin confirmation.</p></div><section className="details-card booking-group-details"><div className="booking-group-list">{bookings.map(booking=>{const dateLabel=new Date(`${booking.booking_date}T12:00:00`).toLocaleDateString('en-PH',{weekday:'long',month:'long',day:'numeric',year:'numeric'});const label=booking.status==='held'?'On hold':booking.status==='pending'?'Awaiting admin confirmation':booking.status==='confirmed'?'Booked':booking.status;return <article className="booking-group-item" key={booking.id}><div className="details-top"><div className="details-primary-lines"><p className="details-primary-date">{dateLabel}</p>{bookingSelections(booking).map(selection=><p className="details-primary-time" key={selection.court_id}><b>{courtLabel(selection.court_id)}:</b> {slotRanges(selection.hours)}</p>)}</div><span className={`badge badge-${booking.status==='held'?'payment-required':booking.status==='pending'?'waiting-confirmation':booking.status==='confirmed'?'approved':booking.status}`}>{label}</span></div><div className="details-facts"><div><small>Play time:</small><b>{booking.duration_hours} hour{booking.duration_hours===1?'':'s'}</b></div><div><small>RATE</small><b>{peso(Math.round(booking.total_price/Math.max(1,booking.duration_hours)))}/hour</b></div><div><small>TOTAL</small><b>{peso(booking.total_price)}</b></div></div>{booking.status==='held'&&<HoldExpiryNotice booking={booking} onExpired={()=>{setMessage('One of the 10-minute holds expired. Please start a new reservation.');void load()}}/>}</article>})}</div>{bookings.length===2&&<div className="booking-group-total"><span>Combined total</span><b>{peso(total)}</b></div>}{error&&<div className="alert alert-error">{error}</div>}{message&&<div className="alert alert-success"><Check size={17}/>{message}</div>}{held.length===bookings.length&&bookings.length===2&&<><div className="hold-payment-info"><h3>GCash details for later payment</h3><GcashNumber/><img className="gcash-payment-qr" src="/gcash-payment-qr-code.png" alt="GCash and InstaPay payment QR code"/><a className="qr-download-link" href="/gcash-payment-qr-code.png" download="Stag-Base-GCash-QR.png"><Download size={14}/> Save QR image</a><p className="payment-transfer-note">Payment is optional now. Combined total: {peso(total)}. Pay at least 50% of the total booking amount.</p><a className="gcash-details-link" href="/gcash-payment-qr.png" target="_blank" rel="noreferrer">View full GCash / InstaPay details</a><small>Payment can be made later. The admin will review both court selections.</small></div><button className="button button-dark full-button" disabled={busy} onClick={submit}>{busy?'Submitting both reservations…':'Book now for both courts'} <ArrowRight size={16}/></button><button className="cancel-link booking-group-cancel" disabled={busy} onClick={cancelAll}>Cancel both holds</button><p className="summary-note"><ShieldCheck size={14}/> The two bookings are submitted together; each remains on hold until the admin confirms it.</p></>}{held.length===0&&bookings.length>0&&<p className="summary-note"><ShieldCheck size={14}/> Payment is optional. The admin must confirm each court booking before it becomes booked and sends the confirmation email.</p>}</section></main>
}

function HoldExpiryNotice({booking,onExpired,variant='inline'}:{booking:any;onExpired:()=>void;variant?:'inline'|'modal'}) {
 const storedExpiry=Date.parse(booking.hold_expires_at)
 const expiresAt=Number.isFinite(storedExpiry)?storedExpiry:Date.parse(booking.created_at)+10*60*1000
 const [secondsRemaining,setSecondsRemaining]=useState(()=>Math.max(0,Math.ceil((expiresAt-Date.now())/1000)))
 useEffect(()=>{
  if(!Number.isFinite(expiresAt))return
  let expired=false
  const tick=()=>{
   const remaining=Math.max(0,Math.ceil((expiresAt-Date.now())/1000))
   setSecondsRemaining(remaining)
   if(remaining===0&&!expired){expired=true;void (async()=>{await supabase?.rpc('get_slot_availability',{p_court_id:booking.court_id,p_booking_date:booking.booking_date});onExpired()})()}
  }
  tick()
  const timer=window.setInterval(tick,1000)
  return()=>window.clearInterval(timer)
 },[booking.id,expiresAt])
 const minutes=String(Math.floor(secondsRemaining/60)).padStart(2,'0')
 const seconds=String(secondsRemaining%60).padStart(2,'0')
 return variant==='modal'?<div className={`hold-timer-holder${secondsRemaining===0?' expired':''}`}><span className="hold-timer-label">{secondsRemaining>0?'TEMPORARY HOLD':'HOLD EXPIRED'}</span><div className="hold-clock"><Clock3 size={15}/><b>{minutes}:{seconds}</b></div><span className="hold-timer-message">{secondsRemaining>0?'Book now or cancel before it expires.':'Releasing this time…'}</span></div>:<div className={`hold-clock${secondsRemaining===0?' expired':''}`}><Clock3 size={16}/><span>{secondsRemaining>0?`Temporary hold · ${minutes}:${seconds} remaining. Click Book now or cancel before it expires.`:'The 10-minute hold expired. Releasing this time…'}</span></div>
}

function UnpaidBookingCard({booking,onApprove,onReject,busy}:{booking:Booking;onApprove:()=>void;onReject:()=>void;busy:boolean}){return <article className="proof-card unpaid-booking-card"><div className="proof-info"><span className="eyebrow">{booking.reference}</span><h3 className="pending-customer-name">{booking.customer_name||booking.profiles?.full_name||'Customer'}</h3><p>{booking.customer_email||booking.profiles?.email||''}</p><div className="pending-booking-facts"><div><small>DATE</small><b>{bookingDateLabel(booking.booking_date)}</b></div><div><small>Play time:</small><b>{bookingPlayTimeLabel(booking)}</b></div><div><small>COURT</small><b>{bookingCourtsLabel(booking)}</b></div><div><small>TOTAL FEE</small><b>{peso(booking.total_price)}</b></div></div><span className="badge badge-waiting-confirmation">On hold</span></div><div className="proof-actions"><button className="button button-lime" disabled={busy} onClick={onApprove}>Confirm</button><button className="button button-reject" disabled={busy} onClick={onReject}>Reject booking</button></div></article>}

function AdminDashboard(){const [rows,setRows]=useState<Booking[]>([]);const [payments,setPayments]=useState<any[]>([]);const [receivedTotals,setReceivedTotals]=useState<Record<string,number>>({});const [filter,setFilter]=useState('confirmed');const [courtFilter,setCourtFilter]=useState('all');const [dateFilter,setDateFilter]=useState(localDate());const [search,setSearch]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');const [selectedBooking,setSelectedBooking]=useState<Booking|null>(null);const notificationBookingId=new URLSearchParams(window.location.search).get('bookingId');useEffect(()=>{if(!notificationBookingId||!rows.length)return;const target=rows.find(booking=>booking.id===notificationBookingId);if(target){setSelectedBooking(target);window.history.replaceState({},'',window.location.pathname)}},[rows,notificationBookingId]);function moveBookingDate(days:number){const next=new Date(`${dateFilter}T12:00:00`);next.setDate(next.getDate()+days);setDateFilter(`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-${String(next.getDate()).padStart(2,'0')}`)}
 async function load(){if(!supabase)return;await supabase.rpc('expire_booking_holds');const [{data,error},{data:pData,error:pError}]=await Promise.all([supabase.from('bookings').select('*,profiles(full_name,email)').order('booking_date',{ascending:false}),supabase.from('payments').select('*,bookings!inner(id,reference,user_id,court_id,court_selections,selected_hours,start_hour,duration_hours,booking_date,total_price,status,payment_method,customer_name,customer_email,customer_phone,profiles(full_name,email))').eq('status','proof_submitted').eq('bookings.status','pending').order('submitted_at')]);if(error||pError)setError(error?.message||pError?.message||'Could not load admin data');setRows((data||[]) as Booking[]);setPayments(pData||[]);const {data:txData,error:txError}=await supabase.from('booking_payment_transactions').select('booking_id,amount');if(txError)setError('Payment ledger unavailable. Apply the booking payment migration. '+txError.message);setReceivedTotals((txData||[]).reduce((totals,row)=>({...totals,[row.booking_id]:(totals[row.booking_id]||0)+Number(row.amount)}),{} as Record<string,number>))} useEffect(()=>{void load()},[]);useEffect(()=>{const client=supabase;if(!client)return;let debounceTimer:number|undefined;const scheduleReload=()=>{if(debounceTimer!==undefined)window.clearTimeout(debounceTimer);debounceTimer=window.setTimeout(()=>void load(),250)};const channel=client.channel('admin-dashboard-booking-refresh').on('postgres_changes',{event:'*',schema:'public',table:'bookings'},scheduleReload).on('postgres_changes',{event:'*',schema:'public',table:'payments'},scheduleReload).on('postgres_changes',{event:'*',schema:'public',table:'booking_payment_transactions'},scheduleReload).subscribe();const fallback=window.setInterval(()=>void load(),20000);return()=>{if(debounceTimer!==undefined)window.clearTimeout(debounceTimer);window.clearInterval(fallback);void client.removeChannel(channel)}},[])
 async function decide(id:string,decision:'verify'|'reject',amountReceived?:number,requestId?:string):Promise<boolean>{setBusy(true);setError('');const {error}=await supabase!.rpc('admin_review_booking_payment_proof',{p_payment_id:id,p_decision:decision,p_amount_received:decision==='verify'?amountReceived:null,p_request_id:requestId||null});if(error){setBusy(false);setError(error.message);return false}let emailSent=false;if(decision==='verify'){const {data:payment}=await supabase!.from('payments').select('booking_id').eq('id',id).single();if(payment?.booking_id){const {error:emailError}=await sendBookingConfirmationEmail(payment.booking_id);if(emailError){const detail=await edgeFunctionErrorMessage(emailError);setBusy(false);setError(`Payment approved, but confirmation email failed: ${detail}`);void load();return true}emailSent=true}}setBusy(false);setMessage(decision==='verify'?(emailSent?'Payment approved and confirmation email sent.':'Payment approved.'):'Payment proof rejected.');void load();return true}
 async function approveUnpaidBooking(id:string){setBusy(true);setError('');const {error}=await supabase!.rpc('admin_confirm_unpaid_booking',{p_booking_id:id});if(error){setBusy(false);setError(error.message);return}const {error:emailError}=await sendBookingConfirmationEmail(id);setBusy(false);if(emailError)setError('Booking marked as Booked, but confirmation email failed. '+await edgeFunctionErrorMessage(emailError));else setMessage('Booking marked as Booked. Email with GCash payment details sent.');void load()} async function rejectUnpaidBooking(id:string){setBusy(true);setError('');const {error}=await supabase!.rpc('admin_reject_unpaid_booking',{p_booking_id:id});setBusy(false);if(error)setError(error.message);else{setMessage('Booking rejected.');void load()}} async function cancel(id:string){const reason=prompt('Reason for cancelling this booking?');if(!reason)return;const {error}=await supabase!.rpc('admin_cancel_booking',{p_booking_id:id,p_reason:reason});if(error)setError(error.message);else{setMessage('Booking cancelled.');void load()}}
 const visible=rows.filter(r=>(filter==='all'||r.status===filter)&&(courtFilter==='all'||bookingSelections(r).some(selection=>String(selection.court_id)===courtFilter))&&(!dateFilter||r.booking_date===dateFilter)&&(!search||`${r.reference} ${r.customer_name||''} ${r.customer_email||''} ${r.customer_phone||''} ${r.profiles?.full_name||''} ${r.profiles?.email||''}`.toLowerCase().includes(search.toLowerCase())));const today=rows.filter(r=>r.booking_date===localDate()&&r.status==='confirmed');const confirmed=rows.filter(r=>r.status==='confirmed');const pending=rows.filter(r=>r.status==='pending');const unpaidPending=rows.filter(r=>r.status==='pending'&&r.payment_status==='unpaid');const revenue=rows.reduce((sum,b)=>sum+(receivedTotals[b.id]||0),0)
 return <main className="page-shell admin-dashboard-page"><div className="page-intro"><span className="eyebrow">STAG BASE PICKLE HUB · ADMIN</span><h1>Club <em>overview.</em></h1><p>Manage reservations, keep the games moving.</p></div>{error&&<div className="alert alert-error">{error}</div>}{message&&<div className="alert alert-success">{message}</div>}<div className="admin-stats"><Stat label="TODAY" value={today.length}/><Stat label="PENDING APPROVAL" value={pending.length}/><Stat label="AWAITING PAYMENT REVIEW" value={payments.length}/><Stat label="BOOKED" value={confirmed.length}/></div><AdminTools/><AdminPricing/><AdminCourtAvailability/><div className="admin-section"><div className="dashboard-heading"><div><span className="eyebrow">BOOKING APPROVAL</span><h2>Pendings <span className="count-chip">{payments.length+unpaidPending.length}</span></h2></div></div>{payments.length===0&&unpaidPending.length===0?<div className="empty-card compact"><FileCheck2/><p>No pending bookings to review.</p></div>:<div className="proof-list">{unpaidPending.map(b=><UnpaidBookingCard key={b.id} booking={b} onApprove={()=>approveUnpaidBooking(b.id)} onReject={()=>rejectUnpaidBooking(b.id)} busy={busy}/>)}{payments.map(p=><ProofCard key={p.id} payment={p} decide={decide} busy={busy}/>)}</div>}</div><div className="admin-section"><div className="dashboard-heading"><div><span className="eyebrow">COURT SCHEDULE</span><h2>Bookings <span className="count-chip">{visible.length}</span></h2></div></div><div className="admin-filters"><input className="admin-booking-search" placeholder="Search reference or customer" value={search} onChange={e=>setSearch(e.target.value)}/><select value={courtFilter} onChange={e=>setCourtFilter(e.target.value)}><option value="all">Both courts</option><option value="1">Court 1</option><option value="2">Court 2</option></select><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">All statuses</option>{['held','pending','confirmed','rejected','cancelled','completed'].map(s=><option key={s}>{s==='held'?'Payment Required':s}</option>)}</select></div><AdminDaySchedule date={dateFilter} rows={rows} onDateChange={setDateFilter} onMoveDate={moveBookingDate} onViewBooking={setSelectedBooking}/>{[1,2].map(court=><section className="admin-court-schedule" key={court}><div className="dashboard-heading"><div><span className="eyebrow">COURT {court} SCHEDULE</span><h3>{court===1?'The Basic':'The Pro'} <span className="count-chip">{visible.filter(b=>b.court_id===court).length}</span></h3></div></div>{visible.filter(b=>b.court_id===court).length===0?<div className="empty-card compact"><p>No bookings match these filters.</p></div>:<div className="booking-list">{visible.filter(b=>b.court_id===court).map(b=><BookingRow key={b.id} booking={b} onUpload={()=>{}} uploading={false} adminMode onViewDetails={()=>setSelectedBooking(b)} onAdminCancel={()=>cancel(b.id)}/>)}</div>}</section>)}<div className="report-strip"><span>COURT 1 <b>{rows.filter(r=>r.court_id===1).length} bookings</b></span><span>COURT 2 <b>{rows.filter(r=>r.court_id===2).length} bookings</b></span><span>CANCELLED <b>{rows.filter(r=>r.status==='cancelled').length}</b></span><span>VERIFIED <b>{peso(revenue)}</b></span></div></div><AdminPushSettings/>{selectedBooking&&<AdminBookingDetails booking={selectedBooking} onClose={()=>setSelectedBooking(null)}/>}</main>
}
function AdminBookingDetails({booking:initialBooking,onClose}:{booking:Booking;onClose:()=>void}){
 const [booking,setBooking]=useState(initialBooking);const [proofs,setProofs]=useState<any[]>([]);const [transactions,setTransactions]=useState<any[]>([]);const [audit,setAudit]=useState<any[]>([]);const [loading,setLoading]=useState(true);const [amount,setAmount]=useState('');const [method,setMethod]=useState<'cash'|'online'>('cash');const [staff,setStaff]=useState('');const [saving,setSaving]=useState(false);const [error,setError]=useState('');const [message,setMessage]=useState('');const requestId=useRef(crypto.randomUUID());
 const load=async()=>{if(!supabase)return;const [b,p,t,a]=await Promise.all([supabase.from('bookings').select('*,profiles(full_name,email)').eq('id',initialBooking.id).maybeSingle(),supabase.from('payments').select('*').eq('booking_id',initialBooking.id).order('submitted_at',{ascending:false}),supabase.from('booking_payment_transactions').select('*,profiles:received_by(full_name,email)').eq('booking_id',initialBooking.id).order('received_at',{ascending:false}),supabase.from('audit_logs').select('action,details,created_at').eq('entity_type','booking').eq('entity_id',initialBooking.id).order('created_at',{ascending:false})]);if(b.data)setBooking(b.data as Booking);setProofs(p.data||[]);if(t.error)setError('Payment ledger unavailable. Apply the booking payment migration. '+t.error.message);setTransactions(t.data||[]);setAudit(a.data||[]);setLoading(false)};
 useEffect(()=>{void load();if(!supabase)return;const channel=supabase.channel(`admin-booking-detail-${initialBooking.id}`).on('postgres_changes',{event:'*',schema:'public',table:'bookings',filter:`id=eq.${initialBooking.id}`},()=>void load()).on('postgres_changes',{event:'*',schema:'public',table:'payments',filter:`booking_id=eq.${initialBooking.id}`},()=>void load()).on('postgres_changes',{event:'*',schema:'public',table:'booking_payment_transactions',filter:`booking_id=eq.${initialBooking.id}`},()=>void load()).subscribe();return()=>{void supabase?.removeChannel(channel)}},[initialBooking.id]);
 const totalReceived=transactions.reduce((sum,t)=>sum+Number(t.amount),0);const outstanding=Math.max(0,Number(booking.total_price)-totalReceived);const online=booking.payment_method==='online';const depositTransactions=transactions.filter(t=>t.payment_type==='deposit');const balanceTransactions=transactions.filter(t=>t.payment_type==='balance');const label=booking.status==='held'?'On hold':booking.status==='pending'?'On hold':booking.status==='confirmed'||booking.status==='completed'?'Booked':booking.status==='rejected'?'Rejected':booking.status==='cancelled'?'Cancelled':'Payment required';const paymentLabel=booking.payment_status==='fully_paid'?'Fully paid':booking.payment_status==='partially_paid'?'Partially paid':booking.payment_status==='proof_submitted'?'Proof submitted':booking.payment_status==='rejected'?'Rejected':booking.payment_status==='refunded'?'Refunded':'Unpaid';
 async function savePayment(e:FormEvent){e.preventDefault();if(!supabase)return;const parsed=Number(amount);if(!Number.isFinite(parsed)||parsed<=0){setError('Enter an amount greater than zero.');return}if(parsed!==outstanding){setError(`Enter the exact remaining balance of ${peso(outstanding)}.`);return}setSaving(true);setError('');setMessage('');const {error:saveError}=await supabase.rpc('admin_record_booking_payment',{p_booking_id:booking.id,p_amount:parsed,p_payment_method:method,p_request_id:requestId.current,p_received_by_name:staff});setSaving(false);if(saveError){setError(saveError.message);return}requestId.current=crypto.randomUUID();setAmount('');setMessage('Payment details saved.');await load()}
 const statusClass=booking.payment_status==='fully_paid'?'fully-paid':booking.payment_status==='partially_paid'?'partially-paid':'unpaid';
 return <div className="admin-modal-backdrop" onClick={onClose}><section className="admin-modal admin-booking-payment-modal" role="dialog" aria-modal="true" aria-label="Booking details and payment" onClick={e=>e.stopPropagation()}><button className="admin-modal-close" onClick={onClose} aria-label="Close details"><X size={18}/></button><div className="admin-modal-title-row"><div><span className="eyebrow">BOOKING · {booking.reference}</span><h2>Booking Details</h2></div><span className={`payment-status-pill ${statusClass}`}>{paymentLabel}</span></div>
 <div className="admin-booking-summary-grid"><div><small>PLAYER</small><b>{booking.customer_name||booking.profiles?.full_name||'Customer'}</b></div><div><small>COURT</small><b>{bookingCourtsLabel(booking)}</b></div><div><small>TIME</small><b>{bookingTimeOnlyLabel(booking)}</b><span>{bookingCourtHours(booking)} hour{bookingCourtHours(booking)===1?'':'s'} · {booking.payment_method==='online'?'GCash / InstaPay':'Cash'}</span></div></div>
 <div className="admin-total-strip"><span>Total amount</span><b>{peso(booking.total_price)}</b></div><div className="admin-payment-meta"><span>Booking status <b>{label}</b></span><span>Total received <b>{peso(totalReceived)}</b></span></div>
 {online&&<section className="admin-payment-panel"><h3>Deposit</h3>{depositTransactions.length===0?<p className="admin-empty-note">{booking.payment_status==='proof_submitted'?'Payment proof submitted · awaiting admin review.':'No verified deposit recorded.'}</p>:<div className="admin-ledger-history">{depositTransactions.map(t=><div className="admin-transaction-row" key={t.id}><div><small>Amount received</small><b>{peso(Number(t.amount))}</b>{t.payment_proof_id&&<AdminTransactionProofLink paymentId={t.payment_proof_id}/>}</div><div><small>Payment method</small><b>GCash / InstaPay</b></div><div><small>Received by</small><b>{t.received_by_name||t.profiles?.full_name||t.profiles?.email||'Admin'}</b></div><div><small>Received on</small><b>{new Date(t.received_at).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}</b></div></div>)}</div>}<div className="admin-total-strip admin-remaining-strip"><span>Remaining balance</span><b>{peso(outstanding)}</b></div></section>}
 <section className="admin-payment-panel"><h3>Balance Payment</h3>{balanceTransactions.length>0&&<div className="admin-ledger-history">{balanceTransactions.map(t=><div className="admin-transaction-row" key={t.id}><div><small>Amount received</small><b>{peso(Number(t.amount))}</b>{t.payment_proof_id&&<AdminTransactionProofLink paymentId={t.payment_proof_id}/>}</div><div><small>Payment method</small><b>{t.payment_method==='online'?'GCash / InstaPay':'Cash'}</b></div><div><small>Received by</small><b>{t.received_by_name||t.profiles?.full_name||t.profiles?.email||'Admin'}</b></div><div><small>Received on</small><b>{new Date(t.received_at).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}</b></div></div>)}</div>}{outstanding===0?<p className="admin-payment-complete"><Check size={16}/> Fully paid. No balance remains.</p>:['confirmed','completed'].includes(booking.status)?<form className="admin-payment-form" onSubmit={savePayment}><label>Amount received<input type="number" min="0.01" max={outstanding} step="0.01" inputMode="decimal" placeholder="₱0.00" value={amount} onChange={e=>setAmount(e.target.value)} required/></label><label>Payment method<select value={method} onChange={e=>setMethod(e.target.value as 'cash'|'online')}><option value="cash">Cash</option><option value="online">GCash / InstaPay</option></select></label><label>Received by<select value={staff} onChange={e=>setStaff(e.target.value)} required><option value=''>Choose admin</option>{['Admin: Andrew Santiago','Admin: Arra Santiago','Admin: Christian Santiago','Admin: Violeta Santiago'].map(name=><option key={name} value={name}>{name}</option>)}</select></label><div className="admin-outstanding-strip"><span>Outstanding balance</span><b>{peso(outstanding)}</b></div><button className="button button-lime" disabled={saving||Number(amount)!==outstanding||!staff}>{saving?'Saving…':'Save payment details'}</button>{message&&<p className="admin-payment-success">{message}</p>}{error&&<p className="admin-payment-error">{error}</p>}</form>:<p className="admin-empty-note">Balance payments can be recorded after the booking is confirmed.</p>}</section>
 {booking.status==='confirmed'&&<AdminConfirmationEmail bookingId={booking.id}/>}<h3>Payment proof history</h3>{loading?<div className="loading-inline"><div className="spinner"/>Loading payment details…</div>:proofs.length===0?<p className="admin-empty-note">No payment proof has been submitted.</p>:<div className="admin-history-list">{proofs.map(p=><AdminPaymentHistory key={p.id} payment={p}/>)}</div>}<h3>Booking history</h3>{audit.length===0?<p className="admin-empty-note">No booking actions recorded.</p>:<div className="admin-history-list">{audit.map((a,i)=><div className="admin-history-item" key={`${a.action}-${i}`}><b>{a.action.replaceAll('_',' ')}</b><span>{new Date(a.created_at).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}</span>{a.details?.reason&&<small>{a.details.reason}</small>}</div>)}</div>}</section></div>
}
function AdminConfirmationEmail({bookingId}:{bookingId:string}){const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');async function send(){if(!supabase)return;setBusy(true);setError('');setMessage('');const {error}=await sendBookingConfirmationEmail(bookingId);setBusy(false);if(error)setError(await edgeFunctionErrorMessage(error));else setMessage('Confirmation email sent (or was already sent).')}return <div className="admin-email-retry"><button className="button button-outline" disabled={busy} onClick={send}>{busy?'Sending…':'Send confirmation email'}</button>{message&&<small>{message}</small>}{error&&<small className="rejection-reason">{error}</small>}</div>}
function AdminTransactionProofLink({paymentId}:{paymentId:string}){const [loading,setLoading]=useState(false);const [url,setUrl]=useState('');const [error,setError]=useState('');async function openProof(){if(!supabase)return;setLoading(true);setError('');const preview=window.open('about:blank','_blank');if(preview)preview.opener=null;const {data:payment,error:paymentError}=await supabase.from('payments').select('proof_path').eq('id',paymentId).maybeSingle();if(paymentError||!payment?.proof_path){preview?.close();setError('Proof unavailable.');setLoading(false);return}const {data,error:proofError}=await supabase.storage.from('payment-proofs').createSignedUrl(payment.proof_path,60);if(proofError||!data?.signedUrl){preview?.close();setError('Could not open proof.');setLoading(false);return}if(preview)preview.location.assign(data.signedUrl);else setUrl(data.signedUrl);setLoading(false)}return <div className="admin-transaction-proof"><button type="button" className="text-button" disabled={loading} onClick={()=>void openProof()}>{loading?'Opening proof…':'View payment proof'} <ArrowUpRight size={13}/></button>{url&&<a href={url} target="_blank" rel="noreferrer">Open proof <ArrowUpRight size={12}/></a>}{error&&<small>{error}</small>}</div>}
function AdminPaymentHistory({payment}:{payment:any}){const [url,setUrl]=useState('');async function openProof(){if(!supabase)return;const {data}=await supabase.storage.from('payment-proofs').createSignedUrl(payment.proof_path,60);if(data?.signedUrl)setUrl(data.signedUrl)}return <div className="admin-history-item"><b>Proof · {payment.status.replaceAll('_',' ')}</b><span>Submitted {new Date(payment.submitted_at).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}{payment.reviewed_at?` · Reviewed ${new Date(payment.reviewed_at).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}`:''}</span>{payment.rejection_reason&&<small>{payment.rejection_reason}</small>}<button className="text-button" onClick={openProof}>{url?'Open secure proof':'View payment proof'} <ArrowUpRight size={14}/></button>{url&&<a className="proof-open" href={url} target="_blank" rel="noreferrer">Open screenshot <ArrowUpRight size={13}/></a>}</div>}
type ReportPoint={period:string;value:number}
type ReportRow=Booking & {report_customer_name:string;amount_paid:number;outstanding_balance:number|null;report_payment_status:string;report_payment_methods:string[]}
type AdminReportData={period:{from:string;to:string;timezone:string};summary:{total_bookings:number;pending_bookings:number;confirmed_bookings:number;completed_bookings:number;cancelled_bookings:number;rejected_bookings:number;proof_awaiting_review:number;fully_paid_bookings:number;partially_paid_bookings:number;unpaid_bookings:number;confirmed_booking_value:number;average_booking_value:number;outstanding_balance:number;refunded_status_bookings:number};financials:{recognized_collections:number;all_recorded_collections:number;cancelled_booking_collections:number;refunded_status_collections:number;cash_collections:number;online_collections:number};courts:{court_id:number;booked_hours:number;available_hours:number;reservations:number;utilization_percent:number|null}[];utilization:{booked_hours:number;available_hours:number;percent:number};payment_status:Record<string,number>;trends:{bookings:ReportPoint[];revenue:ReportPoint[]};table:{total:number;rows:ReportRow[]};notes:{booking_date_basis:string;revenue_date_basis:string;refunds:string}}
const reportDay=(offset:number,base=localDate())=>{const d=new Date(`${base}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10)}
const reportMonthStart=(date:string)=>`${date.slice(0,7)}-01`
const reportPeriodLabel=(from:string,to:string)=>`${new Date(`${from}T12:00:00Z`).toLocaleDateString('en-PH',{timeZone:'UTC',month:'short',day:'numeric',year:'numeric'})} – ${new Date(`${to}T12:00:00Z`).toLocaleDateString('en-PH',{timeZone:'UTC',month:'short',day:'numeric',year:'numeric'})}`
